import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.DC2M1AAK.js";const m=JSON.parse('{"title":"Domain worksheet — answer these before writing code","description":"","frontmatter":{},"headers":[],"relativePath":"build/worksheet.md","filePath":"build/worksheet.md"}'),s={name:"build/worksheet.md"};function r(d,e,n,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="domain-worksheet-—-answer-these-before-writing-code" tabindex="-1">Domain worksheet — answer these before writing code <a class="header-anchor" href="#domain-worksheet-—-answer-these-before-writing-code" aria-label="Permalink to &quot;Domain worksheet — answer these before writing code&quot;">​</a></h1><p>It front-loads the questions that cost the most when discovered late. Keep the filled copy in the domain folder.</p><h2 id="_1-who-is-the-user-and-what-is-the-money-path" tabindex="-1">1. Who is the user, and what is the money path? <a class="header-anchor" href="#_1-who-is-the-user-and-what-is-the-money-path" aria-label="Permalink to &quot;1. Who is the user, and what is the money path?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Your answer</th></tr></thead><tbody><tr><td>Who talks to the agent? (expertise, device, patience, language register)</td><td></td></tr><tr><td>The ONE flow that must work end to end first</td><td></td></tr><tr><td>The irreversible write (the tool, the backend call)</td><td></td></tr><tr><td>What confirms it (the summary → the explicit yes → <code>confirmed:true</code>)</td><td></td></tr><tr><td>What &quot;done&quot; looks like in the UI (end-state card, deep link, next action)</td><td></td></tr></tbody></table><p>The irreversible write defines everything downstream: the confirm gate, the write guards, the probe, the suite&#39;s most important scenarios.</p><h2 id="_2-domain-decomposition" tabindex="-1">2. Domain decomposition <a class="header-anchor" href="#_2-domain-decomposition" aria-label="Permalink to &quot;2. Domain decomposition&quot;">​</a></h2><p>A domain = one coherent job with its own tool surface, guardrails and eval suite. If two capabilities would share &gt;70% of their tools, they are one domain (compose skills inside it); if their guardrails differ (&quot;never submit without confirmation&quot; vs &quot;summarise freely&quot;), they are separate domains (delegate). Ship exactly one domain first.</p><table tabindex="0"><thead><tr><th>Domain</th><th>Job (one line)</th><th>Tool surface</th><th>Irreversible writes?</th><th>Ship order</th></tr></thead><tbody><tr><td></td><td></td><td></td><td></td><td>1</td></tr></tbody></table><h2 id="_3-the-upstream-api-reality-do-this-before-designing-slots" tabindex="-1">3. The upstream API reality (do this BEFORE designing slots) <a class="header-anchor" href="#_3-the-upstream-api-reality-do-this-before-designing-slots" aria-label="Permalink to &quot;3. The upstream API reality (do this BEFORE designing slots)&quot;">​</a></h2><ul><li>Real endpoints, auth scheme, environments. Which base URLs share a database?</li><li>Does the server validate anything? (Write the field-stripping probe early.)</li><li>Schema warts to preserve (misspelled duplicate keys that are the real fields).</li><li>Reference data (customers, catalogues, locations) and how it is searched; cache label → id.</li><li>The auth contract for acting AS the user. Never let a server-side token substitute in production.</li><li>Whole-document update semantics? Does any GET write?</li></ul><h2 id="_4-slots-and-the-conversation" tabindex="-1">4. Slots and the conversation <a class="header-anchor" href="#_4-slots-and-the-conversation" aria-label="Permalink to &quot;4. Slots and the conversation&quot;">​</a></h2><ul><li>Entity types / variants × purposes → the schema registry: slots, sources (<code>ask</code>, <code>derive_&lt;record&gt;</code>, <code>default</code>, <code>computed</code>, <code>runtime_step:&lt;key&gt;</code>), mandatory sets, ask sets.</li><li>The cascade: which slots derive from a record pick vs must be asked.</li><li>Which moments are the runtime&#39;s (forms, pickers, confirmations) and which the model&#39;s.</li><li>Merge vs replace semantics for corrections (validate merges, preview/create replace).</li><li>The users&#39; register, vocabulary and magnitude conventions → the conversation-behaviour skill.</li></ul><h2 id="_5-trust-and-safety-surface" tabindex="-1">5. Trust and safety surface <a class="header-anchor" href="#_5-trust-and-safety-surface" aria-label="Permalink to &quot;5. Trust and safety surface&quot;">​</a></h2><ul><li>What can a prompt-injected turn do at worst? (A wrong write? Reading another user&#39;s data? A link?)</li><li>What data is sensitive (contact details, identifiers, notes)? Where is it scrubbed or masked?</li><li>Flows the agent must refuse (advice it is not licensed to give).</li></ul><h2 id="_6-evals-and-probes" tabindex="-1">6. Evals and probes <a class="header-anchor" href="#_6-evals-and-probes" aria-label="Permalink to &quot;6. Evals and probes&quot;">​</a></h2><ul><li>Every flow above → a scenario first. The suite is the regression gate.</li><li>The probe: <code>--yes</code>, tagged records, self-cleaning, a report folded into the registry.</li><li>A flake ledger from day one.</li></ul><h2 id="_7-channels" tabindex="-1">7. Channels <a class="header-anchor" href="#_7-channels" aria-label="Permalink to &quot;7. Channels&quot;">​</a></h2><ul><li>[ ] Web widget - [ ] Live draft pane - [ ] Voice notes - [ ] Media upload (upload ≠ attach)</li><li>[ ] Resume / nudges / completion - [ ] Mobile web-view host (docs/SDK-AUTH.md)</li></ul><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/DOMAIN-WORKSHEET.md">docs/DOMAIN-WORKSHEET.md</a> — edit it there; the site mirrors the repository.</small></p>',20)])])}const p=t(s,[["render",r]]);export{m as __pageData,p as default};
